// src/main/java/com/example/ticketdesk/request/WorkRequestDtos.java
// API 입출력 DTO 를 record 로 모아 둡니다. 도메인 객체를 그대로 내보내지 않습니다.
package com.example.ticketdesk.request;

import jakarta.validation.constraints.FutureOrPresent;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.Instant;
import java.time.LocalDate;

public final class WorkRequestDtos {

    private WorkRequestDtos() { }

    /** 등록 입력 — 기본 트랙의 zod 스키마와 같은 규칙 */
    public record CreateRequest(
            @NotBlank(message = "제목을 입력하세요")
            @Size(min = 5, max = 100, message = "제목은 5~100자로 입력하세요")
            String title,

            @NotBlank(message = "내용을 입력하세요")
            @Size(min = 10, max = 4000, message = "내용은 10~4000자로 입력하세요")
            String body,

            @FutureOrPresent(message = "마감일은 오늘 이후여야 합니다")
            LocalDate dueDate) { }

    /** 상태 변경 입력 */
    public record StatusChange(@NotNull(message = "상태를 선택하세요") WorkRequest.Status status) { }

    /** 응답 — 필요한 필드만 골라 내보냅니다 */
    public record Response(
            Long id, String title, String body, LocalDate dueDate,
            WorkRequest.Status status, WorkRequest.Category category,
            WorkRequest.Priority priority, String summary,
            String requesterId, Instant createdAt) {

        public static Response from(WorkRequest w) {
            return new Response(w.getId(), w.getTitle(), w.getBody(), w.getDueDate(),
                    w.getStatus(), w.getCategory(), w.getPriority(), w.getSummary(),
                    w.getRequesterId(), w.getCreatedAt());
        }
    }
}

// lib/requests.ts — 업무 요청의 타입 · 입력 스키마 · (오늘만) 메모리 저장소
// 세션 15에서 저장소 부분을 Supabase 로 바꾸고, 타입과 스키마는 그대로 씁니다.
import { z } from "zod";

export const STATUSES = ["RECEIVED", "IN_PROGRESS", "DONE"] as const;
export const CATEGORIES = ["DATA_EXTRACT", "BATCH_ISSUE", "ACCESS", "REPORT", "ETC"] as const;
export const PRIORITIES = ["LOW", "MEDIUM", "HIGH"] as const;

export type Status = (typeof STATUSES)[number];
export type Category = (typeof CATEGORIES)[number];
export type Priority = (typeof PRIORITIES)[number];

export type WorkRequest = {
  id: string;
  title: string;
  body: string;
  dueDate: string | null;      // YYYY-MM-DD
  status: Status;
  category: Category | null;   // 세션 15에서 AI 가 채움
  priority: Priority | null;
  summary: string | null;
  requesterId: string;
  createdAt: string;           // ISO 8601
};

const today = () => new Date().toISOString().slice(0, 10);

// 등록 입력: 화면이 무엇을 보내든 서버에서 다시 검증합니다
export const createRequestSchema = z.object({
  title: z.string().trim().min(5, "제목은 5자 이상 입력하세요").max(100, "제목은 100자 이하로 입력하세요"),
  body: z.string().trim().min(10, "내용은 10자 이상 입력하세요").max(4000, "내용은 4000자 이하로 입력하세요"),
  dueDate: z.iso.date("날짜 형식은 YYYY-MM-DD 입니다")
    .refine((d) => d >= today(), "마감일은 오늘 이후여야 합니다")
    .optional(),
});
export type CreateRequestInput = z.infer<typeof createRequestSchema>;

export const statusChangeSchema = z.object({ status: z.enum(STATUSES) });
export const listQuerySchema = z.object({ status: z.enum(STATUSES).optional() });

// ── 메모리 저장소 (개발 서버가 다시 읽어도 유지되도록 globalThis 에 둡니다)
const g = globalThis as unknown as { __requests?: Map<string, WorkRequest> };
const store = (g.__requests ??= new Map<string, WorkRequest>());

export function listRequests(status?: Status): WorkRequest[] {
  return [...store.values()]
    .filter((r) => !status || r.status === status)
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

export function getRequest(id: string): WorkRequest | undefined {
  return store.get(id);
}

export function createRequest(input: CreateRequestInput, requesterId: string): WorkRequest {
  const item: WorkRequest = {
    id: crypto.randomUUID(),
    title: input.title,
    body: input.body,
    dueDate: input.dueDate ?? null,
    status: "RECEIVED",
    category: null,
    priority: null,
    summary: null,
    requesterId,
    createdAt: new Date().toISOString(),
  };
  store.set(item.id, item);
  return item;
}

export function updateStatus(id: string, status: Status): WorkRequest | undefined {
  const item = store.get(id);
  if (!item) return undefined;
  const updated = { ...item, status };
  store.set(id, updated);
  return updated;
}

// app/api/requests/route.ts — 목록 조회(GET)와 등록(POST)
import type { NextRequest } from "next/server";
import { z } from "zod";
import { createRequest, createRequestSchema, listQuerySchema, listRequests } from "@/lib/requests";

export async function GET(request: NextRequest) {
  const parsed = listQuerySchema.safeParse({
    status: request.nextUrl.searchParams.get("status") ?? undefined,
  });
  if (!parsed.success) {
    return Response.json(
      { message: "조회 조건을 확인하세요", errors: z.flattenError(parsed.error).fieldErrors },
      { status: 400 },
    );
  }
  return Response.json(listRequests(parsed.data.status));
}

export async function POST(request: NextRequest) {
  let json: unknown;
  try {
    json = await request.json();
  } catch {
    return Response.json({ message: "JSON 형식이 아닙니다" }, { status: 400 });
  }

  const parsed = createRequestSchema.safeParse(json);
  if (!parsed.success) {
    return Response.json(
      { message: "입력값을 확인하세요", errors: z.flattenError(parsed.error).fieldErrors },
      { status: 400 },
    );
  }

  // 로그인은 세션 15에서 붙입니다. 오늘은 고정 사용자로 기록합니다.
  const created = createRequest(parsed.data, "demo-user");
  return Response.json(created, {
    status: 201,
    headers: { Location: `/api/requests/${created.id}` },
  });
}

// app/requests/request-form.tsx — 등록 폼 (클라이언트 컴포넌트)
// 화면은 API 만 부릅니다. 같은 API 를 n8n 이나 다른 시스템도 그대로 씁니다.
"use client";

import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";

type FieldErrors = Record<string, string[] | undefined>;

export function RequestForm() {
  const router = useRouter();
  const [errors, setErrors] = useState<FieldErrors>({});
  const [message, setMessage] = useState("");
  const [pending, setPending] = useState(false);

  async function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = e.currentTarget;
    const data = Object.fromEntries(new FormData(form));
    if (!data.dueDate) delete data.dueDate; // 빈 날짜는 보내지 않음

    setPending(true);
    const res = await fetch("/api/requests", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    });
    setPending(false);

    if (res.status === 400) {
      const body = await res.json();
      setErrors(body.errors ?? {});
      setMessage(body.message ?? "입력값을 확인하세요");
      return;
    }
    if (!res.ok) {
      setMessage("저장하지 못했습니다. 잠시 후 다시 시도하세요.");
      return;
    }
    form.reset();
    setErrors({});
    setMessage("접수되었습니다.");
    router.refresh(); // 서버 컴포넌트 목록 다시 그리기
  }

  return (
    <form onSubmit={onSubmit} style={{ display: "grid", gap: 8 }}>
      <label>제목 <input name="title" required minLength={5} maxLength={100} /></label>
      {errors.title && <small style={{ color: "crimson" }}>{errors.title.join(", ")}</small>}

      <label>내용 <textarea name="body" rows={5} required minLength={10} maxLength={4000} /></label>
      {errors.body && <small style={{ color: "crimson" }}>{errors.body.join(", ")}</small>}

      <label>마감일 <input name="dueDate" type="date" /></label>
      {errors.dueDate && <small style={{ color: "crimson" }}>{errors.dueDate.join(", ")}</small>}

      <button type="submit" disabled={pending}>{pending ? "저장 중…" : "접수"}</button>
      {message && <p role="status">{message}</p>}
    </form>
  );
}

// src/main/java/com/example/ticketdesk/common/ApiErrorHandler.java
// 사내 표준 오류 응답: RFC 9457 ProblemDetail + 업무 코드 + traceId
package com.example.ticketdesk.common;

import com.example.ticketdesk.request.WorkRequestService;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

@RestControllerAdvice(basePackages = "com.example.ticketdesk")
public class ApiErrorHandler extends ResponseEntityExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(ApiErrorHandler.class);

    /** 400 — 필드별 메시지를 errors 에 담아 화면이 입력칸 옆에 보여 줄 수 있게 */
    @Override
    protected ResponseEntity<Object> handleMethodArgumentNotValid(
            MethodArgumentNotValidException ex, HttpHeaders headers,
            HttpStatusCode status, WebRequest request) {
        Map<String, List<String>> errors = new LinkedHashMap<>();
        ex.getBindingResult().getFieldErrors().forEach(fe ->
                errors.computeIfAbsent(fe.getField(), k -> new ArrayList<>()).add(fe.getDefaultMessage()));

        ProblemDetail body = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, "입력값을 확인하세요");
        body.setProperty("code", "REQ-400-VALIDATION");
        body.setProperty("errors", errors);
        return handleExceptionInternal(ex, body, headers, status, request);
    }

    /** 404 — 업무 코드만 붙여서 */
    @ExceptionHandler(WorkRequestService.NotFound.class)
    public ProblemDetail notFound(WorkRequestService.NotFound ex) {
        ProblemDetail body = ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
        body.setProperty("code", "REQ-404");
        return body;
    }

    /** 500 — 내부 정보(스택 트레이스, SQL)는 응답에 넣지 않고 traceId 로 로그와 연결 */
    @ExceptionHandler(Exception.class)
    public ProblemDetail unexpected(Exception ex) {
        String traceId = UUID.randomUUID().toString();
        log.error("처리 중 오류 traceId={}", traceId, ex);
        ProblemDetail body = ProblemDetail.forStatusAndDetail(
                HttpStatus.INTERNAL_SERVER_ERROR, "일시적인 오류입니다. 문의 시 추적 번호를 알려 주세요.");
        body.setProperty("code", "SYS-500");
        body.setProperty("traceId", traceId);
        return body;
    }
}

"""app/schemas.py — 업무 요청의 값 목록 · 입력 검증 · 응답 모양.

Next.js 트랙의 zod 스키마와 같은 규칙 · 같은 메시지를 씁니다 (제목 5~100자, 내용 10~4000자, 마감일 오늘 이후).
응답 필드 이름은 camelCase(dueDate, createdAt)로 맞춥니다.
"""
import re
from datetime import date, datetime
from typing import Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator
from pydantic.alias_generators import to_camel
from pydantic_core import PydanticCustomError

Status = Literal["RECEIVED", "IN_PROGRESS", "DONE"]
Category = Literal["DATA_EXTRACT", "BATCH_ISSUE", "ACCESS", "REPORT", "ETC"]
Priority = Literal["LOW", "MEDIUM", "HIGH"]

DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _length(value: str, lo: int, hi: int, label: str) -> str:
    v = value.strip()
    if len(v) < lo:
        raise PydanticCustomError("too_short", f"{label}은 {lo}자 이상 입력하세요")
    if len(v) > hi:
        raise PydanticCustomError("too_long", f"{label}은 {hi}자 이하로 입력하세요")
    return v


class CreateRequest(BaseModel):
    """등록 입력 — 화면이 무엇을 보내든 서버에서 다시 검증합니다."""

    title: str
    body: str
    due_date: date | None = Field(default=None, alias="dueDate")

    @field_validator("title")
    @classmethod
    def check_title(cls, v: str) -> str:
        return _length(v, 5, 100, "제목")

    @field_validator("body")
    @classmethod
    def check_body(cls, v: str) -> str:
        return _length(v, 10, 4000, "내용")

    @field_validator("due_date", mode="before")
    @classmethod
    def check_due_date(cls, v: object) -> date | None:
        if v is None or v == "":
            return None
        if not isinstance(v, str) or not DATE_RE.match(v):
            raise PydanticCustomError("date_format", "날짜 형식은 YYYY-MM-DD 입니다")
        try:
            d = date.fromisoformat(v)
        except ValueError:
            raise PydanticCustomError("date_format", "날짜 형식은 YYYY-MM-DD 입니다") from None
        if d < date.today():
            raise PydanticCustomError("date_past", "마감일은 오늘 이후여야 합니다")
        return d


class StatusChange(BaseModel):
    status: Status


class WorkRequestOut(BaseModel):
    """응답 — 필드 이름은 camelCase 로 내보냅니다 (FastAPI 는 response_model 을 alias 로 직렬화)."""

    model_config = ConfigDict(alias_generator=to_camel, populate_by_name=True, from_attributes=True)

    id: str
    title: str
    body: str
    due_date: date | None
    status: Status
    category: Category | None
    priority: Priority | None
    summary: str | None
    requester_id: str
    created_at: datetime

"""app/main.py — REST API(/api/requests)와 목록 화면(/requests).

    uvicorn app.main:app --reload --port 8000     # http://localhost:8000/requests · 문서 /docs

FastAPI 는 검증 실패를 기본 422 로 돌려주지만, 팀 규격(이론 1절)에 맞춰 400 과
{"message": ..., "errors": {"필드": ["메시지"]}} 모양으로 바꿉니다.
"""
from pathlib import Path
from typing import Annotated

from fastapi import FastAPI, HTTPException, Query, Request, Response
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from fastapi.templating import Jinja2Templates

from app import store
from app.schemas import CreateRequest, Status, StatusChange, WorkRequestOut

app = FastAPI(title="ticket-desk-py")
templates = Jinja2Templates(directory=Path(__file__).parent / "templates")

# pydantic 기본 메시지(영문)를 사용자 문장으로 바꾸는 표 (사용자 정의 오류는 메시지를 그대로 씀)
MESSAGES = {
    "missing": "필수 항목입니다",
    "string_type": "문자열로 보내야 합니다",
    "literal_error": "허용하지 않는 값입니다",
}


@app.exception_handler(RequestValidationError)
async def validation_error(request: Request, exc: RequestValidationError) -> JSONResponse:
    errs = exc.errors()
    if any(e["type"] == "json_invalid" for e in errs):
        return JSONResponse({"message": "JSON 형식이 아닙니다"}, status_code=400)
    fields: dict[str, list[str]] = {}
    for e in errs:
        name = str(e["loc"][-1]) if len(e["loc"]) > 1 else "body"
        msg = MESSAGES.get(e["type"], e["msg"])
        if e["type"] == "literal_error":
            msg = f"{msg}. 허용: {e['ctx']['expected']}"
        fields.setdefault(name, []).append(msg)
    where = {e["loc"][0] for e in errs}
    message = ("조회 조건을 확인하세요" if "query" in where
               else "상태 값을 확인하세요" if request.method == "PATCH" else "입력값을 확인하세요")
    return JSONResponse({"message": message, "errors": fields}, status_code=400)


def not_found() -> HTTPException:
    return HTTPException(status_code=404, detail="요청을 찾을 수 없습니다")


@app.exception_handler(HTTPException)
async def http_error(_request: Request, exc: HTTPException) -> JSONResponse:
    return JSONResponse({"message": exc.detail}, status_code=exc.status_code)


@app.get("/api/requests", response_model=list[WorkRequestOut])
def list_api(status: Annotated[Status | None, Query()] = None):
    return store.list_requests(status)


@app.post("/api/requests", response_model=WorkRequestOut, status_code=201)
def create_api(body: CreateRequest, response: Response):
    created = store.create_request(body, requester_id="demo-user")   # 로그인은 세션 15에서
    response.headers["Location"] = f"/api/requests/{created.id}"
    return created


@app.get("/api/requests/{request_id}", response_model=WorkRequestOut)
def get_api(request_id: str):
    item = store.get_request(request_id)
    if item is None:
        raise not_found()
    return item


@app.patch("/api/requests/{request_id}", response_model=WorkRequestOut)
def change_status_api(request_id: str, body: StatusChange):
    updated = store.update_status(request_id, body.status)
    if updated is None:
        raise not_found()
    return updated


@app.get("/requests", include_in_schema=False)
def requests_page(request: Request):
    """목록은 서버에서 그리고, 등록은 화면의 JavaScript 가 /api/requests 로 보냅니다."""
    return templates.TemplateResponse(request, "requests.html", {"items": store.list_requests()})

